export function isEnum<K extends keyof typeof ALL_ENUMS>(enumName: K, v: unknown): v is (typeof ALL_ENUMS)[K][number] {
  const list = ALL_ENUMS[enumName] as readonly unknown[];
  return typeof v === 'string' && list.includes(v);
}

